import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {Heading, Link, PageLayout} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'

import CustomImageVersionItem from '../views/components/shared/CustomImageVersionItem'
import type {ImageVersion} from '@github-ui/github-hosted-runners-settings/types/image'
import {PlatformOsType as OsType} from '@github-ui/github-hosted-runners-settings/types/platform'

export interface CustomImageVersionsListPayload {
  entityLogin: string
  imageDefinitionId: string
  imagesListPath: string
  imageName: string
  imageOs: OsType
  imageArchitecture: string
  runnerGroupName?: string
  runnerGroupPath?: string
  isEnterprise: boolean
  latestVersion: string
  totalVersionsSize: number
  versions?: ImageVersion[]
  canWriteCustomImages: boolean
}

export function CustomImageVersionsList() {
  const {
    entityLogin,
    imageDefinitionId,
    imagesListPath,
    imageName,
    imageOs,
    imageArchitecture,
    runnerGroupName,
    runnerGroupPath,
    isEnterprise,
    latestVersion,
    totalVersionsSize,
    versions,
    canWriteCustomImages,
  } = useRoutePayload<CustomImageVersionsListPayload>()
  const versionsCount = versions?.length ?? 0
  const title = `${versionsCount} ${versionsCount === 1 ? 'version' : 'versions'}`

  return (
    <PageLayout padding="none" data-hpc>
      <PageLayout.Header style={{marginBottom: '16px !important'}}>
        <Heading as="h2" className="h2 text-normal pb-1" data-testid="custom-image-versions-title">
          <Link href={imagesListPath} data-testid="subhead-runner-list-path">
            Custom images
          </Link>
          &nbsp;/&nbsp;{imageName}
        </Heading>
        <div className="border-bottom" />
      </PageLayout.Header>
      <PageLayout.Content style={{display: 'flex', flexDirection: 'column'}} as="div">
        {versionsCount === 0 ? (
          <div className="rounded-2 border" data-hpc>
            <Blankslate>
              <Blankslate.Heading>
                <span data-testid="no-versions-error">There are no image versions available.</span>
              </Blankslate.Heading>
            </Blankslate>
          </div>
        ) : (
          <div>
            <div className="d-flex tmp-mb-4">
              <div className="tmp-mr-6">
                <div>
                  <span className="color-fg-muted mr-1">Runner group:</span>
                  {runnerGroupPath ? (
                    <Link href={runnerGroupPath} data-testid="runner-group-link">
                      {runnerGroupName}
                    </Link>
                  ) : (
                    <span data-testid="runner-group-link">{runnerGroupName}</span>
                  )}
                </div>
                <div>
                  <span className="color-fg-muted mr-1">Platform:</span>
                  <span data-testid="image-platform">
                    {imageOs}&nbsp;{imageArchitecture.toLowerCase()}
                  </span>
                </div>
              </div>
              <div className="tmp-mr-6">
                <div>
                  <span className="color-fg-muted mr-1">Image versions:</span>
                  <span data-testid="versions-count">{versionsCount}</span>
                </div>
                <div>
                  <span className="color-fg-muted mr-1">Total size:</span>
                  <span data-testid="versions-size">{totalVersionsSize}&nbsp;GB</span>
                </div>
              </div>
            </div>
            <div className="rounded-2 border" data-hpc>
              <div className="overflow-y-auto" data-testid="display-versions-section">
                <ListView
                  metadata={<ListViewMetadata title={<span data-testid="versions-count-list">{title}</span>} />}
                  title={title}
                  titleHeaderTag="h3"
                >
                  {versions?.map(iv => (
                    <CustomImageVersionItem
                      key={iv.version}
                      entityLogin={entityLogin}
                      imageDefinitionId={imageDefinitionId}
                      isEnterprise={isEnterprise}
                      isLatest={iv.version === latestVersion}
                      version={iv}
                      canWriteCustomImages={canWriteCustomImages}
                    />
                  ))}
                </ListView>
              </div>
            </div>
          </div>
        )}
      </PageLayout.Content>
    </PageLayout>
  )
}
